import{_ as o,r as s,o as i,c as p,e as a,a as l,s as c}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Database-driven Themes - October CMS - 4.x","titleTemplate":false,"description":"Store theme content changes in the database instead of the file system.","frontmatter":{"subtitle":"Store theme content changes in the database instead of the file system."},"headers":[{"level":2,"title":"How Database-driven Templates Behave","slug":"how-database-driven-templates-behave","link":"#how-database-driven-templates-behave","children":[]},{"level":2,"title":"Importing from Database to Filesystem","slug":"importing-from-database-to-filesystem","link":"#importing-from-database-to-filesystem","children":[]},{"level":2,"title":"Database-driven Assets","slug":"database-driven-assets","link":"#database-driven-assets","children":[{"level":3,"title":"How it Works","slug":"how-it-works","link":"#how-it-works","children":[]},{"level":3,"title":"Setup","slug":"setup","link":"#setup","children":[]},{"level":3,"title":"Publishing Assets on Deployment","slug":"publishing-assets-on-deployment","link":"#publishing-assets-on-deployment","children":[]},{"level":3,"title":"Cache Invalidation","slug":"cache-invalidation","link":"#cache-invalidation","children":[]}]}],"relativePath":"4.x/cms/themes/database-themes.md","filePath":"4.x/cms/themes/database-themes.md"}'),r={name:"4.x/cms/themes/database-themes.md"};function d(h,e,u,g,m,k){const t=s("pre-heading"),n=s("post-heading");return i(),p("div",null,[a(t),e[0]||(e[0]=l("h1",null,"Database-driven Themes",-1)),a(n),e[1]||(e[1]=c(`<p>In some cases you may not have access to write to the filesystem to make changes to the theme. Database-driven themes allows you to store all changes to CMS templates in the database. This covers pages, layouts, partials, content files, and language files.</p><p>To enable this feature for a single theme, navigate to <strong>Settings → Frontend Theme</strong>, select <strong>Edit Properties</strong> and check the checkbox called <strong>Save Changes in Database</strong>.</p><p>Alternatively you can enable this feature globally for all themes with the config item <code>cms.database_templates</code> or using the environment variable.</p><div class="language-text extra-class"><pre class="language-text"><code>CMS_DB_TEMPLATES=true
</code></pre></div><h2 id="how-database-driven-templates-behave"><a href="#how-database-driven-templates-behave" class="header-anchor">#</a> How Database-driven Templates Behave</h2><p>When the database layer is active for a theme, edits made in the CMS editor are written to the database instead of the filesystem. Reads check the database first and fall back to the filesystem, so files that have never been edited continue to be served directly from the theme directory.</p><p>Deleting a template via the editor writes a tombstone row to the database. The tombstone hides the filesystem copy from listings and reads, so the file appears deleted across every instance even though the on-disk copy is still present. This is the same mechanism used for templates and language files.</p><h2 id="importing-from-database-to-filesystem"><a href="#importing-from-database-to-filesystem" class="header-anchor">#</a> Importing from Database to Filesystem</h2><p>The <code>theme:copy</code> command can be used to copy the database version of the theme to the filesystem. Simply call the command with the <code>--import-db</code> option. This imports templates, language files, assets, and blueprints in a single pass and applies tombstones by deleting the corresponding on-disk files.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan theme:copy demo --import-db
</code></pre></div><p>To delete all the imported database rows at the same time, use the <code>--purge-db</code> option.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan theme:copy demo --import-db --purge-db
</code></pre></div><h2 id="database-driven-assets"><a href="#database-driven-assets" class="header-anchor">#</a> Database-driven Assets</h2><p>By default, asset files like images and stylesheets do not save in the database and cannot be modified without access to the filesystem. When your application runs across multiple instances with a disposable local filesystem, asset edits made in the CMS editor (theme CSS, JavaScript, images, fonts) need somewhere shared to live. Database-driven assets publishes these files to a shared storage disk so they are immediately visible across every instance.</p><div class="custom-block aside"><p>This feature is intended for multi-instance deployments where the local filesystem cannot be relied upon. For single-instance setups the default filesystem behavior is simpler and recommended.</p></div><h3 id="how-it-works"><a href="#how-it-works" class="header-anchor">#</a> How it Works</h3><p>Theme assets are published to a dedicated <code>assets</code> filesystem disk. In production this disk is typically backed by Amazon S3 or another object storage service, fronted by a CDN. The <code>ASSET_URL</code> environment variable points at the same origin, so URLs generated by <code>asset()</code> resolve to the published location.</p><p>When an asset is edited via the backend, the new bytes are written directly to the <code>assets</code> disk and a database record is created tracking the change. The edit is live across all instances immediately.</p><h3 id="setup"><a href="#setup" class="header-anchor">#</a> Setup</h3><p>Three pieces need to be in place.</p><p><strong>1. Configure the <code>assets</code> filesystem disk</strong></p><p>Add an <code>assets</code> disk to your <code>config/filesystems.php</code>. For an S3-backed setup:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;assets&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;driver&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;s3&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;key&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">env</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;AWS_ACCESS_KEY_ID&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;secret&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">env</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;AWS_SECRET_ACCESS_KEY&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;region&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">env</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;AWS_DEFAULT_REGION&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;bucket&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">env</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;AWS_ASSETS_BUCKET&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">env</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;ASSET_URL&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;visibility&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;public&#39;</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><p>For local development you can point the disk at a public path on the local filesystem instead.</p><p><strong>2. Set the <code>ASSET_URL</code> environment variable</strong></p><p><code>ASSET_URL</code> should point at the same origin as the <code>assets</code> disk. This ensures <code>asset()</code> calls resolve to the published location.</p><div class="language-text extra-class"><pre class="language-text"><code>ASSET_URL=https://cdn.example.com
</code></pre></div><p><strong>3. Enable the feature</strong></p><p>Set the <code>cms.database_assets</code> config item, or use the environment variable.</p><div class="language-text extra-class"><pre class="language-text"><code>CMS_DB_ASSETS=true
</code></pre></div><p>The feature is disabled by default so a fresh checkout of the project does not require shared storage credentials to run.</p><h3 id="publishing-assets-on-deployment"><a href="#publishing-assets-on-deployment" class="header-anchor">#</a> Publishing Assets on Deployment</h3><p>The <code>october:mirror</code> command publishes all theme, module, plugin, and app assets to a filesystem disk when called with the <code>--disk</code> option. Run this as part of your deployment pipeline so the published assets reflect the latest version of the code.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan october:mirror <span class="token parameter variable">--disk</span><span class="token operator">=</span>assets
</code></pre></div><p>The command is additive, meaning it uploads or overwrites files but never deletes. Orphaned files left by code changes can be cleaned up with object storage lifecycle rules at the bucket level if desired. Unchanged files are skipped using a size comparison, use the <code>--checksum</code> option to compare content hashes instead, the <code>--force</code> option to upload everything, or the <code>--dry-run</code> option to preview the upload list.</p><h3 id="cache-invalidation"><a href="#cache-invalidation" class="header-anchor">#</a> Cache Invalidation</h3><p>When an asset changes via the CMS editor, the <code>cms.asset.invalidate</code> event fires with the theme and the changed disk keys. Listen to this event to purge cached copies at your CDN, keeping the core CDN-agnostic.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.asset.invalidate&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$theme</span><span class="token punctuation">,</span> <span class="token variable">$diskPaths</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name static-context">MyCdnProvider</span><span class="token operator">::</span><span class="token function">invalidate</span><span class="token punctuation">(</span><span class="token variable">$diskPaths</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,38))])}const f=o(r,[["render",d]]);export{v as __pageData,f as default};
